// crates/ling-fu/src/normalize.rs
//
// `lingfu normalize <lang>` — translate all keywords, builtin names,
// and file/folder names in a Ling project to a single target language.
//
// Usage:
//   lingfu normalize thai          # normalize everything to Thai
//   lingfu normalize zh            # Chinese
//   lingfu normalize --dry-run en  # preview English normalization
//   lingfu normalize ja --content-only  # only rewrite file contents, no renames
//   lingfu normalize ko --files-only    # only rename files/folders

use colored::*;
use std::path::{Path, PathBuf};
use std::{fs, io};

// ─── Target language ──────────────────────────────────────────────────────────

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Lang {
    En,
    Zh,
    Ja,
    Ko,
    Th,
    Fa,
    Ar,
    He,
    Ur,
    Fr,
    De,
    Ru,
}

impl Lang {
    #[allow(clippy::should_implement_trait)]
    pub fn from_name(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "en" | "english" | "英语" | "英語" | "영어" | "อังกฤษ" => {
                Some(Lang::En)
            },
            "zh" | "chinese" | "中文" | "汉语" | "中国語" | "중국어" | "จีน" => {
                Some(Lang::Zh)
            },
            "ja" | "japanese" | "日本語" | "日语" | "일본어" | "ญี่ปุ่น" => {
                Some(Lang::Ja)
            },
            "ko" | "korean" | "한국어" | "韩语" | "韓国語" | "เกาหลี" => {
                Some(Lang::Ko)
            },
            "th" | "thai" | "ภาษาไทย" | "ไทย" | "泰语" | "タイ語" | "태국어" => {
                Some(Lang::Th)
            },
            "fa" | "persian" | "farsi" | "فارسی" => Some(Lang::Fa),
            "ar" | "arabic" | "العربية" => Some(Lang::Ar),
            "he" | "hebrew" | "עברית" => Some(Lang::He),
            "ur" | "urdu" | "اردو" => Some(Lang::Ur),
            "fr" | "french" | "français" | "francais" => Some(Lang::Fr),
            "de" | "german" | "deutsch" => Some(Lang::De),
            "ru" | "russian" | "русский" => Some(Lang::Ru),
            _ => None,
        }
    }

    pub fn name(self) -> &'static str {
        match self {
            Lang::En => "English",
            Lang::Zh => "Chinese",
            Lang::Ja => "Japanese",
            Lang::Ko => "Korean",
            Lang::Th => "Thai",
            Lang::Fa => "Persian",
            Lang::Ar => "Arabic",
            Lang::He => "Hebrew",
            Lang::Ur => "Urdu",
            Lang::Fr => "French",
            Lang::De => "German",
            Lang::Ru => "Russian",
        }
    }

    fn idx(self) -> usize {
        match self {
            Lang::En => 0,
            Lang::Zh => 1,
            Lang::Ja => 2,
            Lang::Ko => 3,
            Lang::Th => 4,
            Lang::Fa => 5,
            Lang::Ar => 6,
            Lang::He => 7,
            Lang::Ur => 8,
            Lang::Fr => 9,
            Lang::De => 10,
            Lang::Ru => 11,
        }
    }
}

