// ─── Content normalization ────────────────────────────────────────────────────

/// Build a replacement map from the given table slices.
/// Sorted longest-first so shorter aliases never shadow longer ones.
fn build_map_from(target: Lang, tables: &[&[Entry]]) -> Vec<(String, String)> {
    let idx = target.idx();
    let mut map: Vec<(String, String)> = Vec::new();
    for table in tables {
        for (aliases, forms) in table.iter() {
            let target_form = forms[idx];
            for alias in *aliases {
                if *alias != target_form {
                    map.push((alias.to_string(), target_form.to_string()));
                }
            }
        }
    }
    map.sort_by_key(|a| std::cmp::Reverse(a.0.len()));
    map.dedup_by(|a, b| a.0 == b.0);
    map
}

/// Map used for rewriting .ling source content — includes builtins.
fn build_replacement_map(target: Lang) -> Vec<(String, String)> {
    build_map_from(
        target,
        &[
            KEYWORDS,
            BUILTINS_VTEX,
            BUILTINS_SHAPES,
            BUILTINS_OTHER,
            BUILTINS_GFX,
            BUILTINS_AUDIO,
            BUILTINS_MATH,
            BUILTINS_CRYPTO,
            BUILTINS_GEO_CRYPTO,
            BUILTINS_PHASE1,
            BUILTINS_PHYSICS,
            BUILTINS_PHYSICS_FN,
            BUILTINS_DIALOG,
            BUILTINS_AI,
            BUILTINS_ANIM,
            BUILTINS_GAME,
            BUILTINS_INPUT,
            BUILTINS_UI,
            BUILTINS_MUSIC,
            VOCABULARY,
        ],
    )
}

/// Map used for renaming files/folders — keywords + vocabulary only.
/// Builtin function names (audio_tone, vtex_grid, …) should NOT rename folders.
fn build_name_map(target: Lang) -> Vec<(String, String)> {
    build_map_from(target, &[KEYWORDS, VOCABULARY])
}

/// True if character is a word constituent (can appear inside an identifier).
fn is_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

/// Normalize the content of a single .ling source file.
pub fn normalize_content(source: &str, target: Lang) -> String {
    let replacements = build_replacement_map(target);
    let chars: Vec<char> = source.chars().collect();
    let mut out = String::with_capacity(source.len());
    let mut i = 0;
    let n = chars.len();

    while i < n {
        // Skip string literals verbatim
        if chars[i] == '"' {
            out.push(chars[i]);
            i += 1;
            while i < n {
                if chars[i] == '\\' && i + 1 < n {
                    out.push(chars[i]);
                    out.push(chars[i + 1]);
                    i += 2;
                } else if chars[i] == '"' {
                    out.push(chars[i]);
                    i += 1;
                    break;
                } else {
                    out.push(chars[i]);
                    i += 1;
                }
            }
            continue;
        }
        // Skip line comments verbatim
        if chars[i] == '/' && i + 1 < n && chars[i + 1] == '/' {
            while i < n && chars[i] != '\n' {
                out.push(chars[i]);
                i += 1;
            }
            continue;
        }
        // Skip # comments verbatim
        if chars[i] == '#' {
            while i < n && chars[i] != '\n' {
                out.push(chars[i]);
                i += 1;
            }
            continue;
        }

        // Try to match a word starting at i
        if is_word_char(chars[i]) {
            // Collect the full word
            let word_start = i;
            while i < n && is_word_char(chars[i]) {
                i += 1;
            }
            let word: String = chars[word_start..i].iter().collect();

            // Check left boundary (char before word_start must be non-word or SOF)
            let left_ok = word_start == 0 || !is_word_char(chars[word_start - 1]);
            // Right boundary already guaranteed (chars[i] is non-word or EOF)
            let right_ok = i == n || !is_word_char(chars[i]);

            if left_ok && right_ok {
                // Try to match any replacement (longest-first already sorted)
                let mut replaced = false;
                for (alias, target_form) in &replacements {
                    if word == *alias {
                        out.push_str(target_form);
                        replaced = true;
                        break;
                    }
                }
                if !replaced {
                    out.push_str(&word);
                }
            } else {
                out.push_str(&word);
            }
            continue;
        }

        out.push(chars[i]);
        i += 1;
    }

    out
}

// ─── File / folder renaming ───────────────────────────────────────────────────

/// Translate any name (folder, file stem) using the full word map.
/// Tries the whole name as an exact lookup — same vocabulary as content rewrite.
fn translate_name(name: &str, map: &[(String, String)]) -> Option<String> {
    for (alias, target_form) in map {
        if name == alias.as_str() {
            return Some(target_form.clone());
        }
    }
    None
}

fn has_ling_ext(name: &str) -> bool {
    name.ends_with(".ling")
        || name.ends_with(".灵")
        || name.ends_with(".霊")
        || name.ends_with(".령")
        || name.ends_with(".ลิง")
}

// ─── Project walker ───────────────────────────────────────────────────────────

#[derive(Default)]
pub struct NormalizeStats {
    pub files_rewritten: usize,
    pub files_renamed: usize,
    pub dirs_renamed: usize,
    pub unchanged: usize,
}

pub fn normalize_project(
    root: &Path,
    target: Lang,
    dry_run: bool,
    content_only: bool,
    files_only: bool,
) -> io::Result<NormalizeStats> {
    let mut stats = NormalizeStats::default();

    // Separate maps: builtins translate in code but shouldn't rename folders
    let name_map = build_name_map(target);

    // Collect all files and directories before any renaming
    let mut all_files: Vec<PathBuf> = Vec::new();
    let mut dirs: Vec<PathBuf> = Vec::new();
    collect_paths(root, &mut all_files, &mut dirs)?;

    let ling_files: Vec<&PathBuf> = all_files
        .iter()
        .filter(|p| {
            p.file_name()
                .and_then(|n| n.to_str())
                .map(has_ling_ext)
                .unwrap_or(false)
        })
        .collect();

    // ── 1. Normalize .ling file contents ────────────────────────────────────
    if !files_only {
        for path in &ling_files {
            let source = fs::read_to_string(path)?;
            let normalized = normalize_content(&source, target);
            if normalized == source {
                stats.unchanged += 1;
                continue;
            }
            let rel = path.strip_prefix(root).unwrap_or(path);
            if dry_run {
                println!("  {} {}", "~".cyan(), rel.display());
            } else {
                fs::write(path, &normalized)?;
                println!("  {} {}", "✓".green(), rel.display());
            }
            stats.files_rewritten += 1;
        }
    }

    if !content_only {
        // ── 2. Rename ALL files whose stem has a known translation ───────────
        let mut rename_files: Vec<(PathBuf, PathBuf)> = Vec::new();
        for path in &all_files {
            if let Some(file_name) = path.file_name().and_then(|n| n.to_str()) {
                // Split at first '.' to get stem + full extension(s)
                let (stem, exts) = if let Some(dot) = file_name.find('.') {
                    (&file_name[..dot], &file_name[dot..])
                } else {
                    (file_name, "")
                };
                if let Some(new_stem) = translate_name(stem, &name_map) {
                    let new_name = format!("{}{}", new_stem, exts);
                    if new_name != file_name {
                        rename_files.push((path.clone(), path.with_file_name(&new_name)));
                    }
                }
            }
        }
        for (from, to) in rename_files {
            let rel_from = from.strip_prefix(root).unwrap_or(&from);
            let rel_to = to.strip_prefix(root).unwrap_or(&to);
            if dry_run {
                println!(
                    "  {} {} → {}",
                    "mv".yellow(),
                    rel_from.display(),
                    rel_to.display()
                );
            } else {
                fs::rename(&from, &to)?;
                println!(
                    "  {} {} → {}",
                    "mv".yellow(),
                    rel_from.display(),
                    rel_to.display()
                );
            }
            stats.files_renamed += 1;
        }

        // ── 3. Rename directories (deepest first) ────────────────────────────
        let mut dirs_sorted = dirs;
        dirs_sorted.sort_by_key(|a| std::cmp::Reverse(a.components().count()));

        for dir in dirs_sorted {
            if let Some(dir_name) = dir.file_name().and_then(|n| n.to_str())
                && let Some(new_name) = translate_name(dir_name, &name_map)
                && new_name != dir_name
            {
                let new_path = dir.with_file_name(&new_name);
                let rel_from = dir.strip_prefix(root).unwrap_or(&dir);
                let rel_to = new_path.strip_prefix(root).unwrap_or(&new_path);
                if dry_run {
                    println!(
                        "  {} {} → {}",
                        "mv".magenta(),
                        rel_from.display(),
                        rel_to.display()
                    );
                } else {
                    fs::rename(&dir, &new_path)?;
                    println!(
                        "  {} {} → {}",
                        "mv".magenta(),
                        rel_from.display(),
                        rel_to.display()
                    );
                }
                stats.dirs_renamed += 1;
            }
        }
    }

    Ok(stats)
}

fn collect_paths(root: &Path, files: &mut Vec<PathBuf>, dirs: &mut Vec<PathBuf>) -> io::Result<()> {
    for entry in fs::read_dir(root)? {
        let entry = entry?;
        let path = entry.path();
        let name = entry.file_name().into_string().unwrap_or_default();
        if name.starts_with('.') || name == "target" || name == ".ling-build" {
            continue;
        }
        if path.is_dir() {
            dirs.push(path.clone());
            collect_paths(&path, files, dirs)?;
        } else {
            files.push(path);
        }
    }
    Ok(())
}

// ─── Vocabulary / normalizer tests ────────────────────────────────────────────
//
// English and Thai are the reference languages (known-good). These tests assert
// that Chinese, Japanese and Korean have full parity — no missing vocabulary —
// and that normalize_content round-trips every canonical token in every table.
#[cfg(test)]
mod vocab_tests {
    use super::*;

    /// Every translation table, by name, for exhaustive iteration.
    fn all_tables() -> Vec<(&'static str, &'static [Entry])> {
        vec![
            ("KEYWORDS", KEYWORDS),
            ("VTEX", BUILTINS_VTEX),
            ("SHAPES", BUILTINS_SHAPES),
            ("OTHER", BUILTINS_OTHER),
            ("GFX", BUILTINS_GFX),
            ("AUDIO", BUILTINS_AUDIO),
            ("MATH", BUILTINS_MATH),
            ("CRYPTO", BUILTINS_CRYPTO),
            ("GEO_CRYPTO", BUILTINS_GEO_CRYPTO),
            ("PHASE1", BUILTINS_PHASE1),
            ("PHYSICS", BUILTINS_PHYSICS),
            ("PHYSICS_FN", BUILTINS_PHYSICS_FN),
            ("DIALOG", BUILTINS_DIALOG),
            ("AI", BUILTINS_AI),
            ("ANIM", BUILTINS_ANIM),
            ("GAME", BUILTINS_GAME),
            ("INPUT", BUILTINS_INPUT),
            ("UI", BUILTINS_UI),
            ("MUSIC", BUILTINS_MUSIC),
            ("VOCABULARY", VOCABULARY),
        ]
    }

    const LANGS: [(usize, &str); 12] = [
        (0, "en"),
        (1, "zh"),
        (2, "ja"),
        (3, "ko"),
        (4, "th"),
        (5, "fa"),
        (6, "ar"),
        (7, "he"),
        (8, "ur"),
        (9, "fr"),
        (10, "de"),
        (11, "ru"),
    ];

    /// 1. Every form is present and clean (non-empty, no stray whitespace).
    #[test]
    fn forms_are_complete() {
        let mut bad = Vec::new();
        for (tname, table) in all_tables() {
            for (_aliases, forms) in table {
                for (i, code) in LANGS {
                    let f = forms[i];
                    if f.is_empty() || f.trim() != f {
                        bad.push(format!(
                            "{tname}: `{}` has bad {code} form {:?}",
                            forms[0], f
                        ));
                    }
                }
            }
        }
        assert!(bad.is_empty(), "incomplete forms:\n{}", bad.join("\n"));
    }

    /// 2. The English canonical (forms[0]) must be one of its own aliases, so
    ///    `normalize` can recognise English source as input.
    #[test]
    fn english_canonical_is_an_alias() {
        let mut bad = Vec::new();
        for (tname, table) in all_tables() {
            for (aliases, forms) in table {
                if !aliases.contains(&forms[0]) {
                    bad.push(format!("{tname}: `{}` not in its own alias list", forms[0]));
                }
            }
        }
        assert!(
            bad.is_empty(),
            "english canonical missing from aliases:\n{}",
            bad.join("\n")
        );
    }

    /// English homonyms: one English word, two genuinely different concepts. The
    /// normalizer can't disambiguate these from the word alone, so one wins.
    /// Documented + accepted here; everything else must be unambiguous.
    // "dialogue" is a pre-existing case of a different flavor: it and "dialog"
    // are separate VOCABULARY entries that already cross-list each other as
    // aliases (so either word resolves to the same concept in source code),
    // but ko/th/fa/ar/he/ur gave them genuinely different translations —
    // meaning normalize_content("dialogue", ..) can resolve through "dialog"'s
    // entry instead of its own. Same accepted trade-off as the true homonyms
    // below: one wins, documented rather than silently wrong.
    const HOMONYMS: &[&str] = &["sign", "spawn", "dialogue"];

    /// 3. The same English canonical may appear in more than one table only when
    ///    the forms are IDENTICAL (benign redundancy). If a word maps to two
    ///    DIFFERENT translations it is ambiguous — fail unless it is a documented
    ///    homonym.
    #[test]
    fn no_ambiguous_duplicate_canonicals() {
        use std::collections::HashMap;
        let mut seen: HashMap<&str, [&str; 12]> = HashMap::new();
        let mut bad = Vec::new();
        for (tname, table) in all_tables() {
            for (_a, forms) in table {
                if HOMONYMS.contains(&forms[0]) {
                    continue;
                }
                if let Some(prev) = seen.insert(forms[0], *forms) {
                    if prev != *forms {
                        bad.push(format!(
                            "{tname}: `{}` ambiguous — {:?} vs {:?}",
                            forms[0], prev, forms
                        ));
                    }
                }
            }
        }
        assert!(
            bad.is_empty(),
            "ambiguous duplicate canonicals:\n{}",
            bad.join("\n")
        );
    }

    /// 4. MISSING-VOCAB GUARD: wherever Thai translated a concept (th != en),
    ///    Chinese, Japanese, Korean, Persian, Arabic, Hebrew and Urdu must
    ///    translate it too (form != en). English + Thai are the reference pair
    ///    the project trusts.
    /// French and German are Indo-European cousins of English (Latin/Germanic
    /// shared roots), so a nontrivial slice of vocabulary is a legitimate
    /// cognate or an internationally-shared technical/proper name (algorithm
    /// names, physics/geometry terms, gaming loanwords, acronyms) rather than
    /// a forgotten translation — unlike the CJK/Semitic set above, where any
    /// match really did mean "nobody translated this yet". Documented here so
    /// the guard still catches real gaps without flagging correct cognates.
    const COGNATE_OK: &[&str] = &[
        "aabb",
        "aes_gcm_256",
        "animation",
        "argon2id",
        "assets",
        "audio",
        "audio_blip",
        "bass",
        "blake3",
        "boss",
        "capsule",
        "chakra",
        "client",
        "collision",
        "contact",
        "concert",
        "cube",
        "demo",
        "dialog",
        "dialogue",
        "ed25519",
        "fbm",
        "fft_rms",
        "force",
        "fps",
        "hash",
        "hkdf_sha3",
        "icon",
        "image",
        "in",
        "init",
        "instrument",
        "intro",
        "level",
        "lotus",
        "mandala",
        "menu",
        "mlkem768",
        "note",
        "parser",
        "pause",
        "perlin",
        "pi",
        "piano",
        "piston",
        "prefab",
        "renderer",
        "ring",
        "router",
        "sample",
        "scripts",
        "server",
        "sha3_256",
        "sha3_512",
        "shader",
        "shake256",
        "sprite",
        "symbol",
        "synth",
        "system",
        "tau",
        "terrain",
        "text",
        "texture",
        "torus",
        "triangle",
        "tween",
        "ui",
        "ui_radar",
        "ui_ring",
        "ui_tooltip",
        "ui_vignette",
        "video",
        "x25519",
        "xchacha20",
    ];

    #[test]
    fn no_missing_zh_ja_ko_where_thai_translates() {
        let mut gaps = Vec::new();
        for (tname, table) in all_tables() {
            for (_a, forms) in table {
                let en = forms[0];
                let th = forms[4];
                if th == en {
                    continue;
                } // concept not translated (proper noun) — skip
                for (i, code) in [
                    (1, "zh"),
                    (2, "ja"),
                    (3, "ko"),
                    (5, "fa"),
                    (6, "ar"),
                    (7, "he"),
                    (8, "ur"),
                    (9, "fr"),
                    (10, "de"),
                    (11, "ru"),
                ] {
                    if forms[i] == en && !COGNATE_OK.contains(&en) {
                        gaps.push(format!("{tname}: `{en}` missing {code} (th=`{th}`)"));
                    }
                }
            }
        }
        assert!(
            gaps.is_empty(),
            "{} missing translations:\n{}",
            gaps.len(),
            gaps.join("\n")
        );
    }

    /// 5. Round-trip: normalising the English canonical to a language yields that
    ///    language's form, for every table entry, for every supported language.
    #[test]
    fn english_normalizes_to_each_language() {
        let mut bad = Vec::new();
        for (tname, table) in all_tables() {
            for (_a, forms) in table {
                if HOMONYMS.contains(&forms[0]) {
                    continue;
                } // winner is by-design one sense
                for (i, lang) in [
                    (1, Lang::Zh),
                    (2, Lang::Ja),
                    (3, Lang::Ko),
                    (4, Lang::Th),
                    (5, Lang::Fa),
                    (6, Lang::Ar),
                    (7, Lang::He),
                    (8, Lang::Ur),
                    (9, Lang::Fr),
                    (10, Lang::De),
                    (11, Lang::Ru),
                ] {
                    let got = normalize_content(forms[0], lang);
                    if got != forms[i] {
                        bad.push(format!(
                            "{tname}: {:?} -> {} gave `{got}`, want `{}`",
                            forms[0],
                            lang.name(),
                            forms[i]
                        ));
                    }
                }
            }
        }
        assert!(
            bad.is_empty(),
            "{} round-trip mismatches:\n{}",
            bad.len(),
            bad.join("\n")
        );
    }
}
